"    if (window.require) {
      try {
        const { ipcRenderer } = window.require('electron');
        for (const printerName of printConfig.names) {
          for (const label of copies) {
            const labelHtml = label ? `<div class="center bold" style="font-size: 11px; margin-top: 1mm;">(${label})</div>` : '';
            const copyHtml = receiptHtml
              .replace('__COPY_LABEL_PLACEHOLDER__', labelHtml)
              .replace('<script>window.onload = () => { window.print(); window.close(); }</script>', '');
            ipcRenderer.send('print-silent', {
              html: copyHtml,
              printerName: printerName
            });
          }
        }
        return;
      } catch (err) {
        console.error("Silent print failed:", err);
      }
    }"

